import React, { useState, useRef, useEffect } from 'react';
import { Upload, X, Loader2, Image as ImageIcon, Smartphone } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { resolveWerseeFileUrl, uploadWerseeFile } from '../services/werseeStorage';
import { QRCodeSVG } from 'qrcode.react';
import { toast } from 'sonner';

interface FileUploadProps {
  bucket: string;
  onUpload: (url: string) => void;
  accept?: string;
  maxSizeMB?: number;
  label?: string;
  darkMode?: boolean;
  compact?: boolean;
  iconOnly?: boolean;
  customTrigger?: React.ReactNode;
  logicalPathPrefix?: string;
  renderPreview?: (url: string, mimeType: string) => React.ReactNode;
}

type UploadProgressState = {
  percent: number;
  transferred: number;
  total: number;
};

const formatMegabytes = (bytes: number) =>
  `${(bytes / (1024 * 1024)).toFixed(bytes >= 10 * 1024 * 1024 ? 1 : 2)} MB`;

const UploadProgress = ({
  progress,
  darkMode,
}: {
  progress: UploadProgressState;
  darkMode: boolean;
}) => (
  <div className="w-full">
    <div className={`flex justify-between text-xs font-semibold tabular-nums ${darkMode ? 'text-white' : 'text-gray-700'}`}>
      <span>Uploading to Wersee Storage</span>
      <span>{progress.percent}%</span>
    </div>
    <div
      role="progressbar"
      aria-label="Wersee Storage upload progress"
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={progress.percent}
      className={`mt-2 h-2 w-full overflow-hidden rounded-full ${darkMode ? 'bg-white/10' : 'bg-black/10'}`}
    >
      <div
        className="h-full rounded-full bg-blue-500 transition-[width] duration-150"
        style={{ width: `${progress.percent}%` }}
      />
    </div>
    <div className={`mt-1 text-[11px] tabular-nums ${darkMode ? 'text-white/50' : 'text-gray-500'}`}>
      {formatMegabytes(progress.transferred)} of {formatMegabytes(progress.total)}
    </div>
  </div>
);

export const FileUpload = ({ 
  bucket, 
  onUpload, 
  accept = "image/*,video/*", 
  maxSizeMB = 50,
  label = "Upload Image or Video",
  darkMode = false,
  compact = false,
  iconOnly = false,
  customTrigger,
  logicalPathPrefix = '',
  renderPreview,
}: FileUploadProps) => {
  const [uploading, setUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState<UploadProgressState>({
    percent: 0,
    transferred: 0,
    total: 0,
  });
  const [preview, setPreview] = useState<string | null>(null);
  const [previewMimeType, setPreviewMimeType] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);
  const localPreviewRef = useRef<string | null>(null);
  const [sessionId, setSessionId] = useState<string>('');
  const [isDesktop, setIsDesktop] = useState(false);
  const onUploadRef = useRef(onUpload);

  useEffect(() => {
    onUploadRef.current = onUpload;
  }, [onUpload]);

  useEffect(() => {
    setIsDesktop(window.innerWidth > 768);
    
    // Generate a unique session ID for mobile upload
    const newSessionId = Math.random().toString(36).substring(2, 15);
    setSessionId(newSessionId);

    // Subscribe to realtime updates for this session
    const channel = supabase.channel(`mobile_upload_${newSessionId}`)
      .on('broadcast', { event: 'upload_complete' }, (payload) => {
        if (payload.payload.url) {
          setPreview(payload.payload.url);
          onUploadRef.current(payload.payload.url);
        }
      })
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  useEffect(() => () => {
    if (localPreviewRef.current) URL.revokeObjectURL(localPreviewRef.current);
  }, []);

  const replacePreview = (url: string | null, mimeType = '') => {
    if (localPreviewRef.current && localPreviewRef.current !== url) {
      URL.revokeObjectURL(localPreviewRef.current);
      localPreviewRef.current = null;
    }
    setPreview(url);
    setPreviewMimeType(mimeType);
  };

  const convertToWebP = (file: File): Promise<Blob> => {
    return new Promise((resolve, reject) => {
      const img = new Image();
      const sourceUrl = URL.createObjectURL(file);
      img.onload = () => {
        URL.revokeObjectURL(sourceUrl);
        const canvas = document.createElement('canvas');
        canvas.width = img.width;
        canvas.height = img.height;
        const ctx = canvas.getContext('2d');
        if (!ctx) {
          reject(new Error('Canvas context not available'));
          return;
        }
        ctx.drawImage(img, 0, 0);
        canvas.toBlob((blob) => {
          if (blob) resolve(blob);
          else reject(new Error('Conversion failed'));
        }, 'image/webp', 0.8);
      };
      img.onerror = (error) => {
        URL.revokeObjectURL(sourceUrl);
        reject(error);
      };
      img.src = sourceUrl;
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > maxSizeMB * 1024 * 1024) {
      toast.error(`File too large. Max size is ${maxSizeMB}MB.`);
      return;
    }

    setUploading(true);
    setUploadProgress({ percent: 0, transferred: 0, total: file.size });
    if (file.type.startsWith('video/') || file.type.startsWith('image/')) {
      const localPreview = URL.createObjectURL(file);
      localPreviewRef.current = localPreview;
      setPreview(localPreview);
      setPreviewMimeType(file.type);
    }
    try {
      let fileToUpload = file;
      let fileExt = file.name.split('.').pop();
      
      // Convert images to WebP
      if (file.type.startsWith('image/')) {
        const webpBlob = await convertToWebP(file);
        fileToUpload = new File([webpBlob], file.name.replace(/\.[^/.]+$/, ".webp"), {
          type: 'image/webp'
        });
        fileExt = 'webp';
      }

      // We don't convert videos to webp, just upload them directly
      const fileName = `${Math.random().toString(36).substring(2)}.${fileExt}`;
      const safePrefix = logicalPathPrefix
        .split('/')
        .map((part) => part.replace(/[^a-zA-Z0-9_-]/g, ''))
        .filter(Boolean)
        .join('/');
      const filePath = safePrefix ? `${safePrefix}/${fileName}` : fileName;

      const object = await uploadWerseeFile({
        bucketId: bucket,
        logicalPath: filePath,
        file: fileToUpload,
        concurrency: fileToUpload.type.startsWith('video/') ? 4 : 3,
        onProgress: ({ percent, transferredBytes, totalBytes }) => {
          setUploadProgress({ percent, transferred: transferredBytes, total: totalBytes });
        },
      });
      const fileUrl = await resolveWerseeFileUrl(bucket, object);

      replacePreview(fileUrl, fileToUpload.type);
      onUploadRef.current(fileUrl);
    } catch (error) {
      console.error('Error uploading file:', error);
      toast.error('Error uploading file');
      replacePreview(null);
    } finally {
      setUploading(false);
    }
  };

  const mobileUploadUrl = `${window.location.origin}/upload-mobile/${sessionId}?bucket=${bucket}`;

  if (customTrigger) {
    return (
      <div onClick={() => fileInputRef.current?.click()} className="cursor-pointer w-full h-full">
        {uploading ? (
          <div className="flex h-full w-full flex-col items-center justify-center gap-3 px-4">
            <Loader2 className={`w-6 h-6 animate-spin ${darkMode ? 'text-white' : 'text-gray-900'}`} />
            <UploadProgress progress={uploadProgress} darkMode={darkMode} />
          </div>
        ) : (
          customTrigger
        )}
        <input
          ref={fileInputRef}
          type="file"
          accept={accept}
          onChange={handleFileChange}
          className="hidden"
        />
      </div>
    );
  }

  if (iconOnly) {
    return (
      <div 
        onClick={() => fileInputRef.current?.click()}
        className={`relative w-full h-full flex items-center justify-center cursor-pointer overflow-hidden transition-colors ${
          darkMode ? 'hover:bg-white/10' : 'hover:bg-black/10'
        }`}
      >
        {uploading ? (
          <>
            <span className="text-xs font-bold tabular-nums text-white">{uploadProgress.percent}%</span>
            <span
              role="progressbar"
              aria-label="Wersee Storage upload progress"
              aria-valuemin={0}
              aria-valuemax={100}
              aria-valuenow={uploadProgress.percent}
              className="absolute inset-x-0 bottom-0 h-1 bg-black/20"
            >
              <span
                className="block h-full bg-blue-500 transition-[width] duration-150"
                style={{ width: `${uploadProgress.percent}%` }}
              />
            </span>
          </>
        ) : (
          <Upload className={`w-6 h-6 ${darkMode ? 'text-white' : 'text-white'}`} />
        )}
        <input
          ref={fileInputRef}
          type="file"
          accept={accept}
          onChange={handleFileChange}
          className="hidden"
        />
      </div>
    );
  }

  return (
    <div className="w-full">
      {preview && !compact ? (
        <div className="relative w-full aspect-video rounded-xl overflow-hidden border border-gray-200 dark:border-white/10 group bg-black">
          {renderPreview ? (
            renderPreview(preview, previewMimeType)
          ) : previewMimeType.startsWith('video/') || preview.match(/\.(mp4|webm|ogg|mov)(?:$|\?)/i) ? (
            <video src={preview} controls className="w-full h-full object-contain" />
          ) : (
            <img src={preview} alt="Preview" className="w-full h-full object-cover" referrerPolicy="no-referrer" />
          )}
          {uploading && (
            <div className="absolute inset-x-3 bottom-3 rounded-xl bg-black/75 p-3 backdrop-blur-md">
              <UploadProgress progress={uploadProgress} darkMode />
            </div>
          )}
          <button
            type="button"
            onClick={() => {
              replacePreview(null);
              if (fileInputRef.current) fileInputRef.current.value = '';
            }}
            disabled={uploading}
            aria-label="Remove preview"
            className="absolute top-2 right-2 p-1 bg-white dark:bg-black rounded-full shadow-md opacity-0 group-hover:opacity-100 transition-opacity z-10"
          >
            <X className="w-4 h-4 text-gray-600 dark:text-gray-300" />
          </button>
        </div>
      ) : (
        <div className={`flex ${compact ? 'flex-col' : 'flex-col sm:flex-row'} gap-4`}>
          <div 
            onClick={() => fileInputRef.current?.click()}
            className={`flex-1 ${compact ? 'h-full' : 'aspect-video'} rounded-xl border-2 border-dashed transition-all flex flex-col items-center justify-center cursor-pointer group ${
              darkMode 
                ? 'border-white/10 hover:border-white/20 hover:bg-[#1A1A1A]' 
                : 'border-gray-300 hover:border-gray-400 hover:bg-gray-50'
            }`}
          >
            {uploading ? (
              <div className="flex w-full flex-col items-center gap-3 px-5">
                <Loader2 className={`w-8 h-8 animate-spin ${darkMode ? 'text-white' : 'text-gray-400'}`} />
                <UploadProgress progress={uploadProgress} darkMode={darkMode} />
              </div>
            ) : (
              <>
                <div className={`p-3 rounded-full ${compact ? 'mb-1' : 'mb-3'} group-hover:scale-110 transition-transform ${
                  darkMode ? 'bg-white/10' : 'bg-gray-100'
                }`}>
                  <Upload className={`${compact ? 'w-4 h-4' : 'w-6 h-6'} ${darkMode ? 'text-gray-400' : 'text-gray-500'}`} />
                </div>
                {!compact && (
                  <>
                    <span className={`text-sm font-medium ${darkMode ? 'text-gray-300' : 'text-gray-600'}`}>{label}</span>
                    <span className={`text-xs mt-1 ${darkMode ? 'text-gray-500' : 'text-gray-400'}`}>Max {maxSizeMB}MB</span>
                  </>
                )}
              </>
            )}
          </div>
          
          {!compact && isDesktop && accept.includes('image') && (
            <div className={`flex-1 aspect-video rounded-xl border flex flex-col items-center justify-center p-4 text-center ${
              darkMode 
                ? 'border-white/10 bg-[#1A1A1A]' 
                : 'border-gray-200 bg-gray-50'
            }`}>
              <div className="bg-white p-2 rounded-xl shadow-sm mb-3">
                <QRCodeSVG value={mobileUploadUrl} size={80} />
              </div>
              <h4 className={`text-sm font-semibold flex items-center gap-1 ${darkMode ? 'text-white' : 'text-[#1D1D1F]'}`}>
                <Smartphone className="w-4 h-4" /> Upload via Mobile
              </h4>
              <p className={`text-xs mt-1 ${darkMode ? 'text-gray-400' : 'text-gray-500'}`}>Scan to take a photo directly</p>
            </div>
          )}
        </div>
      )}
      <input
        ref={fileInputRef}
        type="file"
        accept={accept}
        onChange={handleFileChange}
        className="hidden"
      />
    </div>
  );
};
